 ['versions of the tools used and the packages pytesseract needs', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport PIL, importlib.metadata as md\nprint(tess.get_tesseract_version(), PIL.__version__, md.version('pytesseract'))\nprint(md.requires('pytesseract'))", "5.3.4 12.3.0 0.3.13\n['packaging>=21.3', 'Pillow>=8.0.0']"],
 ['the four lines of the chapter on a rendered line of text, and the same through a file path', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport tempfile, os\nimg = render('Hello OCR world 2026')\ntext = tess.image_to_string(img)\nprint(repr(text))\np = os.path.join(tempfile.mkdtemp(), 'line.png')\nimg.save(p)\nprint(tess.image_to_string(p) == text, tess.image_to_string(Image.open(p)) == text)", "'Hello OCR world 2026\\n'\nTrue True"],
 ['pytesseract runs the tesseract program and returns what it prints', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport subprocess, tempfile, os\nimg = render('Hello OCR world 2026')\np = os.path.join(tempfile.mkdtemp(), 'line.png')\nimg.save(p)\ncli = subprocess.run(['tesseract', p, 'stdout'], capture_output=True, text=True).stdout\nprint(repr(cli), cli.strip() == tess.image_to_string(img).strip())", "'Hello OCR world 2026\\n' True"],
 ['practice questions 1 to 3 and 5: the default language, the functions and the installed packs', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport inspect\nprint(inspect.signature(tess.image_to_string).parameters['lang'].default)\nprint(callable(tess.image_to_string), callable(tess.get_languages), callable(Image.open))\nprint(tess.get_languages())", "None\nTrue True True\n['eng', 'osd']"],
 ['a language pack that is not installed', 'import sys\nsys.path.insert(0, \'/tmp/claude-0/ch22lib\')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new(\'L\', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimg = render(\'Hello OCR world 2026\')\ntry:\n    tess.image_to_string(img, lang=\'jpn\')\nexcept tess.TesseractError as e:\n    print(type(e).__name__, [c.__name__ for c in type(e).__mro__[1:3]], e.status, "Failed loading language \'jpn\'" in e.message)\nprint(repr(tess.image_to_string(img, lang=\'eng+jpn\')))', "TesseractError ['RuntimeError', 'Exception'] 1 True\n'Hello OCR world 2026\\n'"],
 ['a tightly cropped line: default segmentation, a white border, and a single-line mode', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\ntight = render('Hello OCR world 2026').crop(ImageOps.invert(render('Hello OCR world 2026')).getbbox())\nprint(tight.size)\nprint(repr(tess.image_to_string(tight)))\nprint(repr(tess.image_to_string(ImageOps.expand(tight, border=10, fill=255))))\nprint(repr(tess.image_to_string(tight, config='--psm 7')))", "(394, 31)\n''\n'Hello OCR world 2026\\n'\n'Hello OGR world 2026\\n'"],
 ['white text on a dark background under Tesseract 5.3.4', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nlight = render('Hello OCR world 2026')\ndark = ImageOps.invert(light)\nprint(dark.getpixel((0, 0)), light.getpixel((0, 0)))\nprint(repr(tess.image_to_string(dark)))", "0 255\n'Hello OCR world 2026\\n'"],
 ['a slanted line: how far it may turn, and turned back', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimg = render('Hello OCR world 2026')\nfor a in (2, 5, 8, 12):\n    r = img.rotate(a, expand=True, fillcolor=255)\n    back = r.rotate(-a, resample=Image.BICUBIC, fillcolor=255)\n    print(a, repr(tess.image_to_string(r)), repr(tess.image_to_string(back)))", "2 'Hello OCR world 2026\\n' 'Hello OCR world 2026\\n'\n5 'Hello OCR world 2026\\n' 'Hello OCR world 2026\\n'\n8 'Hello OcR world 2026\\n' 'Hello OCR world 2026\\n'\n12 '' 'Hello OCR world 2026\\n'"],
 ['noise and low contrast, and what a median filter and autocontrast do', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport random\nfrom PIL import ImageFilter\nimg = render('Hello OCR world 2026')\nrandom.seed(1)\nnoisy = img.copy()\npx = noisy.load()\nfor _ in range(1500):\n    px[random.randrange(noisy.width), random.randrange(noisy.height)] = random.choice((0, 255))\nprint(repr(tess.image_to_string(noisy)), repr(tess.image_to_string(noisy.filter(ImageFilter.MedianFilter(3)))))\nlow = render('Hello OCR world 2026', fg=170, bg=200)\nprint(low.getextrema(), ImageOps.autocontrast(low).getextrema())\nprint(repr(tess.image_to_string(low)), repr(tess.image_to_string(ImageOps.autocontrast(low))))", "'Hello OCR world 2026\\n' 'Hello OCR world 2026\\n'\n(170, 200) (0, 255)\n'Hello OCR world 2026\\n' 'Hello OCR world 2026\\n'"],
 ['two columns are read across the page', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\ntwo = Image.new('L', (900, 200), 255)\nd = ImageDraw.Draw(two)\nfor xy, t in (((20, 20), 'Left column first line'), ((20, 80), 'Left column second'), ((480, 20), 'Right one'), ((480, 80), 'Right two')):\n    d.text(xy, t, fill=0, font=font)\nprint(repr(tess.image_to_string(two)))\nleft = two.crop((0, 0, 450, 200))\nright = two.crop((450, 0, 900, 200))\nprint(repr(tess.image_to_string(left)), repr(tess.image_to_string(right)))", "'Left column first line Right one\\nLeft column second Right two\\n'\n'Left column first line\\nLeft column second\\n' 'Right one\\nRight two\\n'"],
 ['word boxes and confidences: the header of the table and one word', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimg = render('Hello OCR world 2026')\nrows = tess.image_to_data(img).splitlines()\nprint(rows[0].split('\\t'))\nwords = [r.split('\\t') for r in rows[1:] if r.split('\\t')[11].strip()]\nprint([w[11] for w in words], all(0 <= float(w[10]) <= 100 for w in words))\nd = tess.image_to_data(img, output_type=tess.Output.DICT)\nprint(sorted(d) == sorted(rows[0].split('\\t')), d['text'][-1])", "['level', 'page_num', 'block_num', 'par_num', 'line_num', 'word_num', 'left', 'top', 'width', 'height', 'conf', 'text']\n['Hello', 'OCR', 'world', '2026'] True\nTrue 2026"],
