 ['the call to NAPS2 as a list, with a stand-in program that is not NAPS2', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport subprocess\nstand_in = [sys.executable, '-c', 'import sys; print(sys.argv[1:]); sys.exit(3)']\nproc = subprocess.run(stand_in + ['-i', 'my scan.png', '-o', 'output.pdf', '-f'], capture_output=True)\nprint(proc.returncode, proc.stdout, proc.stderr)\ntry:\n    subprocess.run(stand_in, capture_output=True, check=True)\nexcept subprocess.CalledProcessError as e:\n    print(type(e).__name__, e.returncode)\ntry:\n    subprocess.run(['naps2.console', '-i', 'a.png'], capture_output=True)\nexcept FileNotFoundError as e:\n    print(type(e).__name__)", '3 b"[\'-i\', \'my scan.png\', \'-o\', \'output.pdf\', \'-f\']\\n" b\'\'\nCalledProcessError 3\nFileNotFoundError'],
 ['the practice program without the screenshot: crop, recognise, append, twice', "import sys\nsys.path.insert(0, '/tmp/claude-0/ch22lib')\nfrom PIL import Image, ImageDraw, ImageFont, ImageOps\nimport pytesseract as tess\nfont = ImageFont.load_default(size=40)\ndef render(text, size=(700, 120), fg=0, bg=255):\n    im = Image.new('L', size, bg)\n    ImageDraw.Draw(im).text((20, 30), text, fill=fg, font=font)\n    return im\nimport tempfile, os\nLEFT, TOP, RIGHT, BOTTOM = 400, 200, 1000, 800\ndef fake_screen(text):\n    scr = Image.new('L', (1400, 900), 235)\n    d = ImageDraw.Draw(scr)\n    d.text((20, 20), 'BROWSER MENU', fill=0, font=font)\n    d.rectangle((LEFT, TOP, RIGHT, BOTTOM), fill=255)\n    d.text((LEFT + 40, TOP + 60), text, fill=0, font=font)\n    return scr\nout = os.path.join(tempfile.mkdtemp(), 'output.txt')\nfor page in ('Page one of the scroll', 'Page two of the scroll'):\n    img = fake_screen(page).crop((LEFT, TOP, RIGHT, BOTTOM))\n    with open(out, 'a', encoding='utf-8') as f:\n        f.write(tess.image_to_string(img))\nprint(img.size)\nprint(repr(open(out, encoding='utf-8').read()))", "(600, 600)\n'Page one of the scroll\\nPage two of the scroll\\n'"],
